import{_ as r,l as i,o as e,c as n,v as t,p as E,x as l,d as m,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ROME / MEMIT","description":"","frontmatter":{"title":"ROME / MEMIT","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rome-memit.md","filePath":"llm/rome-memit.md","lastUpdated":1789023840000}'),M={name:"llm/rome-memit.md"};function d(h,a,c,A,T,_){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="rome-memit" tabindex="-1">ROME / MEMIT <a class="header-anchor" href="#rome-memit" aria-label="Permalink to &quot;ROME / MEMIT&quot;">​</a></h1><div class="epigraph"><p>一条事实往往集中在中层 MLP 把主语映射到属性的位置；改那个键值，不必再跑一遍指令 SFT。</p><footer>—— Meng 等，Locating and Editing Factual Associations in GPT（NeurIPS 2022）；Mass-Editing Memory in a Transformer（ICLR 2023）</footer></div><p><a href="/llm/lora-intrinsic-rank">内在秩</a>说明任务适应常落在低维切空间。有时你不要「学会一种任务」，只要改一条关联：Eiffel Tower 在巴黎 → 在罗马。全参或 <a href="/llm/lora">LoRA</a> SFT 会把整份条件分布拖向示范，副作用是邻近事实与口吻一起漂。Meng、Bau、Belinkov 等人的 ROME 先定位后编辑；MEMIT 把同一套键值更新扩到批量事实。本课打开「改一处而不动其他」。不把知识注入的限度（<a href="/llm/knowledge-injection-limits">下一课</a>）写成编辑已成功。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>因果语言建模把事实散在权重与上下文里。用户却按「主语–关系–客体」来想：谁位于哪里。SFT 用自然语言句子教这条，损失沿全序列回传，许多层、许多 token 都动。能否找到一个模块，它以主语的表示为键、以客体为值，像可改写的记忆槽？</p><p>定位若失败，编辑就是在随机层加扰动，等于劣质微调。定位若成功，仍要约束：改巴黎→罗马时，埃菲尔铁塔的高度、法国的首都不应一起变成罗马的。这是局部性指标，不是指令遵循分数。</p><h3 id="中层-mlp-当关联存储器" tabindex="-1">中层 MLP 当关联存储器 <a class="header-anchor" href="#中层-mlp-当关联存储器" aria-label="Permalink to &quot;中层 MLP 当关联存储器&quot;">​</a></h3><p>ROME 用因果追踪：把干净运行与损坏运行的激活对换，看客体 token 的概率何时恢复。发现：在主语最后 token 的位置上，中层 MLP 贡献关键。将该 MLP 的下行投影看成线性关联记忆 \\(W\\)，\\(k\\) 来自主语表示，\\(v\\) 编码客体。编辑变成：解一个约束最小二乘，使 \\(Wk_{\\mathrm{new}}\\approx v_{\\mathrm{new}}\\)，并尽量保持其它已有键。</p><p><span class="marginnote">MEMIT 对多层、多事实同时解约束，把残差分配到一段 MLP 层，避免单层 \\(W\\) 过载。批量不是循环调用 ROME 一千次而不管层间耦合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每条事实构造提示（「The Eiffel Tower is located in」），取主语末 token 在选定层的激活为 \\(k\\)，用优化得到目标 \\(v\\)（使模型在客体位置输出新客体）。ROME 更新单层 \\(W\\)；MEMIT 选一段中层，解联合目标。插入后用生成与闭卷探针检查：目标事实是否改写、释义提示是否泛化、无关事实是否保持。</p><p>这与 SFT 契约正交：不经过<a href="/llm/chat-template">chat template</a> 的助手轮，也可以在基座补全格式上编辑。若产品是对话模型，编辑应在对齐后的权重上做，并用对话提示回归，否则补全编辑与助手行为脱节。</p>',12)),(e(),E(p,null,{default:l(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%9B%A0%E6%9E%9C%E8%BF%BD%E8%B8%AA%E5%AE%9A%E4%BD%8D%22%5D%20--%3E%20K%5B%22%E4%B8%BB%E8%AF%AD%E9%94%AE%20k%22%5D%0A%20%20C%20--%3E%20V%5B%22%E7%9B%AE%E6%A0%87%E5%80%BC%20v%22%5D%0A%20%20K%20--%3E%20U%5B%22%E7%BA%A6%E6%9D%9F%E6%9B%B4%E6%96%B0%20MLP%20%E7%9A%84%20W%22%5D%0A%20%20V%20--%3E%20U%0A%20%20U%20--%3E%20T%5B%22%E7%9B%AE%E6%A0%87%E4%BA%8B%E5%AE%9E%20%2F%20%E9%82%BB%E8%BF%91%E4%BA%8B%E5%AE%9E%20%2F%20%E6%B5%81%E7%95%85%E5%BA%A6%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要用指令数据「再训一遍」代替定位：那是回到全分布适应。编辑失败时先查层是否选对、键是否取在主语末 token，再查约束权重。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MLP 的 \\(W_{\\mathrm{down}}\\) 把高维特征映回残差。若某列方向专门为某主语–属性服务，改 \\(W\\) 使该键指向新值，相当于改写记忆。注意力负责把主语信息送到那个位置；编辑不改注意力，假设路由仍把同一主语送到同一槽。因此对未见句式的泛化取决于键是否稳定：换一种说法若主语表示漂移，编辑不触发。这解释了为何 ROME 在释义上部分泛化、在反向提示（罗马的地标是什么）上常失败——反向是另一条键，下一课的限度。</p><p>MEMIT 把 \\(\\|Wk-v\\|\\) 的残差分到多层，每层改得少，对无关键的破坏小于单层猛改。事实数量超过层容量时，仍会互相覆盖：局部编辑不是无限字典。</p><p><span class="marginnote">与 LoRA 的关系：可以在同一 MLP 上挂 LoRA 去做「可逆编辑」，但几何不同。ROME 直接改已有记忆槽；LoRA 在残差上加一段任务增量。批量事实用 MEMIT 通常比用一个事实表做 LoRA 更局部。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>编辑的是补全型事实探针，不是世界模型。涉及多跳、时间、计数的「事实」常常没有单一槽。安全对齐过的模型上，编辑可能被拒答头盖住：补全显示已改，对话仍拒绝或仍说旧答案。评测协议必须同时含补全与对话。规模上，MEMIT 能到数千条量级（论文设定），不是整部维基。超出则应用检索或接受微调的全局性。</p><p>下一课：即使槽改对了，把新知识当训练数据灌进去仍会幻觉——编辑成功 ≠ 注入成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ROME 用因果追踪把事实定位到主语位置的中层 MLP，再约束更新键值。</li><li>MEMIT 将批量更新分配到多层，减轻单层过载。</li><li>评测要含目标改写、释义泛化、无关事实与流畅度。</li><li>反向提示与多跳常不共享同一键，编辑不自动对称。</li><li>对话对齐模型须在助手提示上回归，不能只看补全。</li><li>出处：Meng 等，ROME，NeurIPS 2022；Meng 等，MEMIT，ICLR 2023。</li></ul>',10))])}const u=r(M,[["render",d]]);export{f as __pageData,u as default};
